package com.sigtm.backend.controller;
import com.sigtm.backend.dto.*; import com.sigtm.backend.model.FacturaProveedor; import com.sigtm.backend.service.CuentaPorPagarService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/cuentas-por-pagar") @RequiredArgsConstructor public class CuentaPorPagarController { private final CuentaPorPagarService service; @GetMapping @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<List<FacturaProveedor>> listar(){return ResponseEntity.ok(service.listar());} @PostMapping @PreAuthorize("hasAuthority('COMPRAS:CREAR')") public ResponseEntity<FacturaProveedor> crear(@Valid @RequestBody CrearFacturaProveedorRequest r){return ResponseEntity.ok(service.crear(r));} @PostMapping("/{id}/pagos") @PreAuthorize("hasAuthority('COMPRAS:APROBAR')") public ResponseEntity<FacturaProveedor> pagar(@PathVariable Long id,@Valid @RequestBody RegistrarPagoProveedorRequest r){return ResponseEntity.ok(service.pagar(id,r));}}
